-- Official MEDIATRON Scopus publication candidates linked to MEDIATRON active/candidate authors.
-- Imported as APPROVED because the source is an official Scopus export.
-- Allow long official Scopus metadata before importing publications.
-- Some Scopus titles and author/source strings are longer than 255 characters.
ALTER TABLE publications
ALTER COLUMN title TYPE TEXT,
    ALTER COLUMN authors_text TYPE TEXT,
    ALTER COLUMN source TYPE TEXT,
    ALTER COLUMN external_url TYPE TEXT,
    ALTER COLUMN pdf_url TYPE TEXT,
    ALTER COLUMN doi TYPE TEXT,
    ALTER COLUMN indexation TYPE TEXT;
CREATE TEMP TABLE tmp_official_mediatron_publications (
    title TEXT,
    publication_year INTEGER,
    authors_text TEXT,
    source_title TEXT,
    doi TEXT,
    external_url TEXT,
    document_type TEXT,
    publication_type TEXT
) ON COMMIT DROP;




-- DOI-based import/update.
SELECT t.title, NULLIF(t.doi, ''), t.publication_year, t.authors_text, 'Scopus', NULLIF(t.external_url, ''), NULL, NULLIF(t.source_title, ''), t.publication_type, 'APPROVED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
FROM tmp_official_mediatron_publications t
WHERE NULLIF(t.doi, '') IS NOT NULL
ON CONFLICT (doi) DO UPDATE SET
    title = EXCLUDED.title,
    publication_year = EXCLUDED.publication_year,
    authors_text = EXCLUDED.authors_text,
    source = EXCLUDED.source,
    external_url = COALESCE(EXCLUDED.external_url, publications.external_url),
    indexation = COALESCE(EXCLUDED.indexation, publications.indexation),
    type = EXCLUDED.type,
    status = 'APPROVED',
    updated_at = CURRENT_TIMESTAMP;

-- Title/year fallback for rows without DOI.
SELECT t.title, NULL, t.publication_year, t.authors_text, 'Scopus', NULLIF(t.external_url, ''), NULL, NULLIF(t.source_title, ''), t.publication_type, 'APPROVED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
FROM tmp_official_mediatron_publications t
WHERE NULLIF(t.doi, '') IS NULL
  AND NOT EXISTS (
      SELECT 1 FROM publications p
      WHERE LOWER(p.title) = LOWER(t.title)
        AND COALESCE(p.publication_year, -1) = COALESCE(t.publication_year, -1)
  );